package com.example.meetomxh;

import android.content.Intent;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.content.ContextCompat;
import com.example.meetomxh.models.Chat;
import com.example.meetomxh.repositories.ChatRepository;
import com.example.meetomxh.supabase.*;
import org.json.JSONArray;
import org.json.JSONObject;

/** Per-user conversation controls; every setting is authorized by its own RPC. */
public final class ConversationDetailsActivity extends AppCompatActivity {
    public static final String EXTRA_CHAT_ID="chat_id";
    private String chatId,peerId; private Switch muteSwitch; private Button blockButton,reportButton; private TextView conversationName,peerUsername; private Button manageButton,archiveButton,profileButton,searchButton,sharedPostsButton,inviteButton,renameButton,leaveButton; private boolean archived; private ImageView avatar; private Button avatarButton; private TextView memberCount; private com.example.meetomxh.storage.SupabaseStorage.Transfer avatarUpload;
    private final androidx.activity.result.ActivityResultLauncher<String> avatarPicker=registerForActivityResult(new androidx.activity.result.contract.ActivityResultContracts.GetContent(),uri->{if(uri!=null)uploadAvatar(uri);});
    @Override protected void onCreate(Bundle state){super.onCreate(state);chatId=getIntent().getStringExtra(EXTRA_CHAT_ID);if(chatId==null){finish();return;}buildUi();load();}
    private void buildUi(){
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(ContextCompat.getColor(this,R.color.app_bg));
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(12),dp(8),dp(16),dp(8));header.setBackgroundColor(ContextCompat.getColor(this,R.color.surface_bg));
        TextView back=new TextView(this);back.setText("‹");back.setTextSize(34);back.setTextColor(ContextCompat.getColor(this,R.color.text_primary));header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));back.setOnClickListener(v->finish());
        TextView title=new TextView(this);title.setText("Chi tiết hội thoại");title.setTextSize(18);title.setTextColor(ContextCompat.getColor(this,R.color.text_primary));title.setTypeface(null,1);header.addView(title);root.addView(header);
        ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(20),dp(20),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        avatar=new ImageView(this);body.addView(avatar,new LinearLayout.LayoutParams(dp(88),dp(88)));memberCount=new TextView(this);memberCount.setTextColor(getColor(R.color.text_secondary));body.addView(memberCount);avatarButton=button("Đổi ảnh nhóm");avatarButton.setVisibility(View.GONE);body.addView(avatarButton,lp());avatarButton.setOnClickListener(v->avatarPicker.launch("image/*"));
        conversationName=new TextView(this);conversationName.setId(View.generateViewId());conversationName.setText("Đang tải…");conversationName.setTextSize(20);conversationName.setTextColor(ContextCompat.getColor(this,R.color.text_primary));conversationName.setTypeface(null,1);body.addView(conversationName);
        peerUsername=new TextView(this);peerUsername.setTextColor(ContextCompat.getColor(this,R.color.text_secondary));body.addView(peerUsername);
        TextView subtitle=new TextView(this);subtitle.setText("Cài đặt áp dụng cho tài khoản của bạn.");subtitle.setTextColor(ContextCompat.getColor(this,R.color.text_secondary));body.addView(subtitle,new LinearLayout.LayoutParams(-1,-2));
        addDivider(body);
        Button gallery=button("Ảnh và video đã chia sẻ");body.addView(gallery,lp());gallery.setOnClickListener(v->{try{startActivity(new Intent(this,SharedMediaGalleryActivity.class).putExtra(SharedMediaGalleryActivity.EXTRA_CHAT_ID,chatId));}catch(RuntimeException e){Toast.makeText(this,"Không thể mở ảnh và video đã chia sẻ. Hãy thử lại.",Toast.LENGTH_SHORT).show();}});
        searchButton=button("Tìm kiếm tin nhắn");body.addView(searchButton,lp());searchButton.setOnClickListener(v->startActivity(new Intent(this,ConversationSearchActivity.class).putExtra(ConversationSearchActivity.EXTRA_CHAT_ID,chatId)));
        sharedPostsButton=button("Bài viết/Reels đã chia sẻ");body.addView(sharedPostsButton,lp());sharedPostsButton.setOnClickListener(v->startActivity(new Intent(this,SharedPostsActivity.class).putExtra(SharedPostsActivity.EXTRA_CHAT_ID,chatId)));
        muteSwitch=new Switch(this);muteSwitch.setText("Tắt thông báo hội thoại");muteSwitch.setTextColor(ContextCompat.getColor(this,R.color.text_primary));muteSwitch.setPadding(0,dp(14),0,dp(14));body.addView(muteSwitch,lp());muteSwitch.setOnCheckedChangeListener((b,checked)->setMuted(checked));
        profileButton=button("Xem hồ sơ");body.addView(profileButton,lp());profileButton.setOnClickListener(v->{if(peerId!=null)startActivity(new Intent(this,ProfileActivity.class).putExtra("target_uid",peerId));});
        manageButton=button("Thành viên nhóm");body.addView(manageButton,lp());manageButton.setVisibility(View.GONE);manageButton.setOnClickListener(v->startActivity(new Intent(this,GroupMembersActivity.class).putExtra(GroupMembersActivity.EXTRA_CHAT_ID,chatId)));
        inviteButton=button("Thêm thành viên");body.addView(inviteButton,lp());inviteButton.setVisibility(View.GONE);inviteButton.setOnClickListener(v->withChat(c->ChatControls.invite(this,c)));
        renameButton=button("Đổi tên nhóm");body.addView(renameButton,lp());renameButton.setVisibility(View.GONE);renameButton.setOnClickListener(v->Api.run(()->ChatRepository.getInstance().load(chatId),new Api.Callback<Chat>(){public void success(Chat c){ChatControls.rename(ConversationDetailsActivity.this,c,ConversationDetailsActivity.this::load);}public void error(String e){Toast.makeText(ConversationDetailsActivity.this,e,Toast.LENGTH_LONG).show();}}));
        leaveButton=button("Rời nhóm");body.addView(leaveButton,lp());leaveButton.setVisibility(View.GONE);leaveButton.setOnClickListener(v->withChat(c->ChatControls.leave(this,c)));
        archiveButton=button("Lưu trữ hội thoại");body.addView(archiveButton,lp());archiveButton.setOnClickListener(v->{archiveButton.setEnabled(false);Api.run(()->RpcClient.call("set_conversation_archived",Api.obj("p_conversation_id",chatId,"p_archived",!archived)),new Api.Callback<Object>(){public void success(Object r){archived=!archived;archiveButton.setEnabled(true);archiveButton.setText(archived?"Bỏ lưu trữ":"Lưu trữ hội thoại");}public void error(String e){archiveButton.setEnabled(true);Toast.makeText(ConversationDetailsActivity.this,e,Toast.LENGTH_LONG).show();}});});
        blockButton=button("Chặn người dùng");body.addView(blockButton,lp());blockButton.setOnClickListener(v->toggleBlock());
        reportButton=button("Báo cáo tài khoản");body.addView(reportButton,lp());reportButton.setOnClickListener(v->{if(peerId!=null)startActivity(new Intent(this,ReportContentActivity.class).putExtra(ReportContentActivity.EXTRA_TARGET_TYPE,"profile").putExtra(ReportContentActivity.EXTRA_TARGET_ID,peerId));});
        blockButton.setVisibility(View.GONE);reportButton.setVisibility(View.GONE);
        setContentView(root);
    }
    private void load(){Api.run(()->{Chat c=ChatRepository.getInstance().load(chatId);JSONArray blocked=(JSONArray)RpcClient.call("list_blocked_users",new JSONObject());return new Object[]{c,blocked};},new Api.Callback<Object[]>(){public void success(Object[] v){Chat c=(Chat)v[0];JSONArray blocked=(JSONArray)v[1];for(String id:c.getParticipants())if(!id.equals(SessionManager.getInstance().uid()))peerId=id;conversationName.setText(c.title);com.example.meetomxh.ui.AvatarViews.load(avatar,c.avatar,"neutral");memberCount.setText("group".equals(c.getType())?c.getParticipants().size()+" thành viên":"");avatarButton.setVisibility("group".equals(c.getType())&&"admin".equals(c.role)?View.VISIBLE:View.GONE);archived=c.archived;archiveButton.setText(archived?"Bỏ lưu trữ":"Lưu trữ hội thoại");boolean group="group".equals(c.getType());manageButton.setVisibility(group?View.VISIBLE:View.GONE);inviteButton.setVisibility(group&&"admin".equals(c.role)?View.VISIBLE:View.GONE);renameButton.setVisibility(group&&"admin".equals(c.role)?View.VISIBLE:View.GONE);leaveButton.setVisibility(group?View.VISIBLE:View.GONE);searchButton.setVisibility(group||peerId!=null?View.VISIBLE:View.GONE);sharedPostsButton.setVisibility(group||peerId!=null?View.VISIBLE:View.GONE);profileButton.setVisibility(group?View.GONE:View.VISIBLE);peerUsername.setVisibility(group?View.GONE:View.VISIBLE);if("private".equals(c.getType())&&peerId!=null)ProfileClient.get(peerId,new Api.Callback<com.example.meetomxh.models.User>(){public void success(com.example.meetomxh.models.User p){String name=p.getFullName();conversationName.setText(name==null||name.trim().isEmpty()?"Người dùng không khả dụng":name);peerUsername.setText(p.username==null||p.username.trim().isEmpty()?"":"@"+p.username);com.example.meetomxh.ui.AvatarViews.load(avatar,p.getAvatarUrl(),p.getAvatarPreset());}public void error(String e){conversationName.setText("Người dùng không khả dụng");peerUsername.setText("");}});muteSwitch.setOnCheckedChangeListener(null);muteSwitch.setChecked(c.muted);muteSwitch.setOnCheckedChangeListener((b,checked)->setMuted(checked));boolean isBlocked=false;for(int i=0;i<blocked.length();i++)if(peerId!=null&&peerId.equals(blocked.optJSONObject(i).optString("user_id")))isBlocked=true;blockButton.setText(isBlocked?"Bỏ chặn người dùng":"Chặn người dùng");blockButton.setTag(isBlocked);blockButton.setVisibility("private".equals(c.getType())?View.VISIBLE:View.GONE);reportButton.setVisibility("private".equals(c.getType())?View.VISIBLE:View.GONE);}public void error(String e){Toast.makeText(ConversationDetailsActivity.this,e,Toast.LENGTH_LONG).show();}});}
    private interface ChatAction{void run(Chat chat);}
    private void withChat(ChatAction action){Api.run(()->ChatRepository.getInstance().load(chatId),new Api.Callback<Chat>(){public void success(Chat c){action.run(c);}public void error(String e){Toast.makeText(ConversationDetailsActivity.this,e,Toast.LENGTH_LONG).show();}});}
    private void setMuted(boolean value){muteSwitch.setEnabled(false);Api.run(()->RpcClient.call("set_conversation_muted",Api.obj("p_conversation_id",chatId,"p_muted",value)),new Api.Callback<Object>(){public void success(Object v){muteSwitch.setEnabled(true);Toast.makeText(ConversationDetailsActivity.this,value?"Đã tắt thông báo":"Đã bật thông báo",Toast.LENGTH_SHORT).show();}public void error(String e){muteSwitch.setOnCheckedChangeListener(null);muteSwitch.setChecked(!value);muteSwitch.setOnCheckedChangeListener((b,checked)->setMuted(checked));muteSwitch.setEnabled(true);Toast.makeText(ConversationDetailsActivity.this,e,Toast.LENGTH_LONG).show();}});}
    private void toggleBlock(){if(peerId==null)return;boolean blocked=Boolean.TRUE.equals(blockButton.getTag());new AlertDialog.Builder(this).setTitle(blocked?"Bỏ chặn người dùng?":"Chặn người dùng?").setMessage(blocked?"They may be able to contact you again.":"They will not be able to send you messages while blocked.").setNegativeButton("Hủy",null).setPositiveButton(blocked?"Unblock":"Block",(d,w)->{blockButton.setEnabled(false);Api.run(()->RpcClient.call("set_block",Api.obj("p_target",peerId,"p_blocked",!blocked)),new Api.Callback<Object>(){public void success(Object r){blockButton.setTag(!blocked);blockButton.setText(!blocked?"Bỏ chặn người dùng":"Chặn người dùng");blockButton.setEnabled(true);Toast.makeText(ConversationDetailsActivity.this,!blocked?"Đã chặn người dùng":"Đã bỏ chặn",Toast.LENGTH_SHORT).show();}public void error(String e){blockButton.setEnabled(true);Toast.makeText(ConversationDetailsActivity.this,e,Toast.LENGTH_LONG).show();}});}).show();}
    private void uploadAvatar(android.net.Uri uri){avatarButton.setEnabled(false);avatarUpload=com.example.meetomxh.storage.SupabaseStorage.upload(getContentResolver(),uri,"avatar",SessionManager.getInstance().uid(),new com.example.meetomxh.storage.SupabaseStorage.UploadListener(){public void onProgress(int p){avatarButton.setText("Đang tải "+p+"%");}public void onSuccess(String ref){Api.run(()->RpcClient.call("set_conversation_avatar",Api.obj("p_conversation_id",chatId,"p_asset_id",Dto.assetId(ref))),new Api.Callback<Object>(){public void success(Object r){avatarButton.setEnabled(true);avatarButton.setText("Đổi ảnh nhóm");load();}public void error(String e){avatarButton.setEnabled(true);avatarButton.setText("Thử đổi ảnh lại");Toast.makeText(ConversationDetailsActivity.this,e,Toast.LENGTH_LONG).show();}});}public void onFailure(String e){avatarButton.setEnabled(true);avatarButton.setText("Thử đổi ảnh lại");Toast.makeText(ConversationDetailsActivity.this,e,Toast.LENGTH_LONG).show();}});}
    @Override protected void onResume(){super.onResume();if(conversationName!=null)load();}
    @Override protected void onDestroy(){if(avatarUpload!=null)avatarUpload.cancel();super.onDestroy();}
    private Button button(String text){Button b=new Button(this);b.setText(text);b.setAllCaps(false);return b;} private LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);p.bottomMargin=dp(8);return p;} private void addDivider(LinearLayout p){View v=new View(this);v.setBackgroundColor(ContextCompat.getColor(this,R.color.divider_color));LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-1,dp(1));l.topMargin=dp(16);l.bottomMargin=dp(16);p.addView(v,l);}private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
}
